from itertools import product
PF,PS={1:.1,0:.9},{1:.3,0:.7}
PA={(1,1):.95,(1,0):.8,(0,1):.4,(0,0):.05}
PN={1:.9,0:.2}
def J(f,s,a,n):
    pa=PA[f,s] if a else 1-PA[f,s]; pn=PN[a] if n else 1-PN[a]
    return PF[f]*PS[s]*pa*pn
num=sum(J(1,s,a,1) for s,a in product((0,1),(0,1)))
den=sum(J(f,s,a,1) for f,s,a in product((0,1),(0,1),(0,1)))
print(num,den,round(num/den,3))

